def drive(me, enemy, arena):
    # target a point to the enemy's left side to avoid its front wedge
    heading_rad = radians(enemy.heading)
    offset = 1.2
    target_x = enemy.x + offset * sin(heading_rad)
    target_y = enemy.y - offset * cos(heading_rad)

    # if close, just aim at centre
    if distance_to(enemy.x, enemy.y) < 1.0:
        target_x, target_y = enemy.x, enemy.y

    bearing = bearing_to(target_x, target_y)   # -180..180, positive = left
    if bearing > 20:
        return (0.6, -0.6)   # turn left
    elif bearing < -20:
        return (-0.6, 0.6)   # turn right
    else:
        return (1.0, 1.0)    # go straight


def weapons(me, enemy, arena):
