        cmds = []
        for slot in ("front", "back"):
            w = me.weapons.get(slot)
            if w and w["type"] == "spinner":
                cmds.append(spin(slot, w["max_rpm"]))
        me.memory["spun_up"] = True
        if cmds:
            return cmds
    return None

